(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ru"] = {"ui":{"skip":"Перейти к содержимому","back":"← Назад к AI-gile","lang.button":"Язык: {name}","lang.dialog":"Выбери язык","lang.search":"Найти язык","lang.none":"Подходящих языков нет","lang.notYet":"{name} пока не переведён","theme.aria":"Сменить тему: светлая, тёмная или чёрная","theme.toLight":"Включить светлую тему","theme.toDark":"Включить тёмную тему","theme.toBlack":"Включить чёрную тему (настоящий чёрный, бережёт OLED-экраны)","words.underline":"Подчеркнуть эти слова на странице","words.underlineHelp":"Наведи курсор на слово с пунктирным подчёркиванием или нажми на него, чтобы узнать, что оно значит.","words.col.todo":"Карточки, выбранные на сейчас: команда возьмётся за них следующими.","words.col.doing":"Сейчас над этой карточкой работает ИИ.","words.col.review":"Один ИИ закончил работу; другой проверяет её, прежде чем она дойдёт до тебя.","words.col.verify":"Ждёт тебя: попробуй и скажи, работает ли.","words.col.team":"Твои заметки или ответы, которые ждут, пока команда их подхватит.","words.col.done":"Готово и принято.","index.title":"AI-gile: твоя команда ИИ-разработчиков на одной доске","index.description":"AI-gile это канбан-доска для команд ИИ-программистов. Они работают, пока ты спишь, а тебе остаётся одна короткая стопка: что решить, что проверить и что принять.","hero.logoAlt":"Значок доски AI-gile","hero.h1.html":"Твоя команда ИИ-разработчиков на одной&nbsp;доске.","hero.alpha":"🐣 Закрытая пре-альфа","hero.alphaTitle":"Ещё сыро и не закончено: спасибо, что пробуешь!","hero.lede":"Они строят, пока ты спишь. Утром тебя ждёт одна короткая стопка: пара вопросов, пара вещей на проверку, один-два фиолетовых ромбика. Клик, принял, и обратно к кофе.","dl.windows":"Приложение для Windows","dl.browser":"Запустить в браузере","dl.messenger":"📱 Messenger для телефона","dl.soon":"Скоро","dl.notify":"🔔 Напиши, когда откроется","dl.notifySmall":"Альфа или бета","hero.secondary":"Agile, только команде не нужен кофе на стендапе. (Стендапы они всё равно проводят.)","pitch.h2":"AI-gile в любом количестве слов","pitch.lede":"Выбери длину: от одного слова до 144. Каждая длина это отдельное описание, написанное именно под неё. Двигай ползунок или жми стрелки.","pitch.rangeLabel":"Длина в словах","pitch.dice":"🎲 другой вариант","pitch.words.one":"{n} слово","pitch.words.other":"{n} слова","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} буквы","pitch.chars.one":"{n} символ","pitch.chars.other":"{n} символа","count.line.html.one":"{n} карточка на доске прямо сейчас","count.line.html.other":"{n} карточки на доске прямо сейчас","people.humans.html.one":"👥 {n} человек","people.humans.html.other":"👥 {n} человек","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агентов","people.working.html.one":"⚡ {n} в работе прямо сейчас","people.working.html.other":"⚡ {n} в работе прямо сейчас","pre.title":"AI-gile: здесь что-то строится","pre.description":"Здесь что-то строится: доска, на которой ИИ-команды строят то, что ты просишь, и по ходу дела учат тебя. Пока что закрытая пре-альфа для друзей.","pre.h1":"Здесь что-то строится. 🤫","pre.line":"Доска, на которой ИИ-команды строят то, что ты просишь, и по ходу дела учат тебя. Пока что закрытая пре-альфа для друзей.","pre.btn":"🔔 Напиши, когда откроется","pre.peek":"За стеклом: настоящая доска, вживую. Каждая карточка — цветная полоска.","pre.peekFake":"За стеклом: так выглядит доска в работе.","features.aria":"Что она делает","f.pile.h":"Одна стопка для тебя","f.pile.html":"<b>Тебе</b> собирает всё, что ждёт тебя, из всех проектов: вопросы, вещи на проверку, задачи, которые под силу только человеку. Твоя очередь подскажет, что дальше и сколько это займёт.","f.sleep.h":"Команды, которые работают, пока ты спишь","f.sleep.p":"У каждого проекта есть лид и команда ИИ-агентов. Оставь комментарий к карточке, команда проснётся, сделает работу и вернёт её с шагами, которые осилит даже уставший человек.","f.tester.h":"Сначала проверяет ИИ-тестировщик","f.tester.p":"Прежде чем что-то дойдёт до тебя, тестировщик проходит шаги в копии приложения и показывает, что увидел, со скриншотом. Пролистай прошедшее проверку и прими одним кликом.","f.proof.h":"Доказательства, а не обещания","f.proof.p":"Каждая сдача показывает, что изменилось: файлы, diff, скриншоты. Не нужно открывать каждое приложение, чтобы узнать, готово ли оно.","f.chat.h":"Общайся со своими лидами","f.chat.p":"Боковая панель как в Discord: по значку на проект, фиолетовые ромбики там, где нужен ты. Напиши лиду идею, и он превратит её в карточки и план, а тебе останется кнопка ✅ Go.","f.tidy.h":"Сама наводит порядок","f.tidy.p":"Похожие карточки сливаются в одну, запутанные названия исправляются, а проверка токенов следит, чтобы код не разбухал. Меньше переключений, меньше лишних мыслей.","f.private.h":"Твоя, на твоём компьютере","f.private.li1":"Доска работает на твоём компьютере и отвечает только тебе.","f.private.li2":"Личные сообщения между людьми защищены сквозным шифрованием.","f.private.li3":"Никаких аккаунтов, трекеров и cookie.","f.lang.h":"На твоём языке","f.lang.p":"Больше 120 языков: от нидерландского, валлийского и японского до пиратского, языка Йоды и клингонского, и быстрый переход на английский для профессионального жаргона.","f.service.h":"От идеи до настоящего сервиса","f.service.p":"Сделал с ИИ что-то, чем теперь пользуются люди? Отметь это как сервис, и доска поможет вести его как следует: проверки доступности, публичная страница статуса, инциденты с разбором, изменения, которым нужно Go, ежедневная проверка резервных копий. Справка объясняет каждый шаг по ходу дела.","msgr.h2":"AI-gile Messenger: твоя команда в кармане","msgr.p1":"Общайся со своей ИИ-командой, не открывая доску. Переписывайся с лидами проектов и друзьями, смотри шаги проверки карточки и отвечай на них, всё с телефона.","msgr.p2":"Чтобы связать его с доской, отсканируй на ней QR-код. Впервые? Дружелюбный демо-чат всё покажет.","msgr.when":"Сначала Android, потом веб-версия для телефонов и iPhone.","msgr.who":"Твой лид проекта","msgr.b1":"Исправление тёмной темы готово. Прислать шаги проверки?","msgr.b2":"Да, пожалуйста!","msgr.b3":"1. Открой Настройки. 2. Выбери Тёмную. Всё выглядит как надо?","tl.aria":"Хронология от первого разговора до дорожной карты","tl.h2":"От первого разговора до того, что дальше","tl.lede":"Настоящие даты и время в твоём часовом поясе. После сегодняшнего дня идёт план, без обещанных дат.","tl.today":"Сегодня","tl.planned":"в планах","tl.doing":"в работе","tl.cards.one":"{n} карточка","tl.cards.other":"{n} карточки","join.h2":"Присоединяйся","join.lede":"AI-gile строят бородатый чудак с AuDHD и несколькими битвами за психическое здоровье — и множество терпеливых агентов. Пока всё закрыто: закрытая альфа для друзей. Хочешь попробовать, когда откроется?","join.btn":"Оставить заявку","join.small":"Напишем на почту, и больше ничего","footer.tag":"AI-gile. Без трекеров, без cookie, без кофе на стендапе.","footer.licence":"Лицензия для бизнеса","footer.status":"Статус","footer.privacy":"Что мы храним","footer.thanks":"Звонки благодаря ChilledChat","form.sending":"Отправляю…","form.failed":"Не вышло: попробуй позже.","form.offline":"Не удалось связаться с AI-gile: попробуй позже.","form.keep":"Мы используем это только чтобы ответить тебе, а потом удаляем. Без трекеров и cookie.","form.keepLink":"Что мы храним","interest.title":"AI-gile: напиши мне, когда откроется альфа","interest.description":"Оставь почту, чтобы узнать, когда откроется закрытая альфа или бета AI-gile.","interest.h1":"🔔 Напиши, когда откроется","interest.lede":"AI-gile в закрытой пре-альфе. Оставь почту, и мы напишем один раз, когда для тебя найдётся место.","interest.email":"Твоя почта","interest.which":"Какой тест?","interest.alpha":"Закрытая альфа: рано, сыро, много изменений","interest.beta":"Бета: стабильнее, позже","interest.both":"Любой, что раньше","interest.submit":"Внесите меня в список","interest.thanks":"Спасибо! Ты в списке.","licence.title":"AI-gile: лицензия для бизнеса","licence.description":"Используешь AI-gile в бизнесе? Подай заявку на бесплатную лицензию.","licence.h1":"📜 Лицензия для бизнеса","licence.lede":"Используешь AI-gile на работе? Расскажи, кто ты и чем занимаешься. Если это приносит пользу, лицензия бесплатна.","licence.company":"Компания","licence.website":"Сайт","licence.what":"Чем занимаешься","licence.how":"Чем это помогает миру","licence.email":"Почта","licence.submit":"Отправить заявку","licence.thanks":"Спасибо! Ответим по почте.","status.title":"Статус AI-gile","status.h1":"Статус AI-gile","status.quiet":"Всё тихо","status.intro":"AI-gile сейчас работает? Эта страница каждые 5 минут проверяет сайт, общий доступ к доскам, звонки и загрузку.","status.up":"Работает (ответ за {ms} мс)","status.slow":"Не ответил при последней проверке, пробую снова","status.down":"Не работает: не ответил на две последние проверки","status.svc.web":"Сайт","status.svc.web.offers":"Этот сайт: что такое AI-gile, и форма записи в список","status.svc.boards":"Общий доступ к доскам","status.svc.boards.offers":"Публичные доски, сообщения между друзьями и приглашения","status.svc.calls":"Звонки","status.svc.calls.offers":"Голос, видео и демонстрация экрана в AI-gile","status.svc.download":"Загрузка","status.svc.download.offers":"Установщик для Windows и ссылки-приглашения","status.checking":"Проверяю…","status.offline":"Сейчас не получается связаться со службой статуса (пробую снова)","status.updated":"обновлено {ago}","status.justNow":"только что","status.min":"{n} мин назад","status.hours":"{n} ч назад","status.days":"{n} д назад","privacy.title":"AI-gile: что мы храним","privacy.h1":"Что мы храним","privacy.lede":"Коротко: только то, что ты нам отправишь, и ненадолго.","privacy.only":"Только то, что ты нам отправляешь: то, что вводишь в форму, например свою почту. Больше ничего о тебе.","privacy.sealed":"Всё запечатывается, так что наш сервер не может это прочитать: прямо в твоём браузере, ещё до отправки (в старом браузере — в момент получения). Открыть это может только наша собственная доска.","privacy.server":"С сервера это удаляется, как только попадает на нашу доску. Всё, что пролежит там дольше 30 дней, удаляется в любом случае.","privacy.board":"На нашей доске мы храним это только до тех пор, пока не ответим тебе, а потом удаляем и оттуда.","privacy.none":"Без трекеров, без cookie, без аналитики.","privacy.local":"Твой язык и выбор светлой или тёмной темы остаются в твоём браузере. Нам они никогда не отправляются.","privacy.ask":"Хочешь, чтобы это удалили раньше? Ответь на наше письмо и скажи об этом.","live.h2":"Смотрите, как это строится, в прямом эфире","live.caption":"Каждая карточка скрыта: вы видите форму работы, а не слова.","live.watching.one":"в эфире: смотрит {n}","live.watching.other":"в эфире: смотрят {n}","live.last.now":"Последняя карточка перемещена только что","live.last.min.one":"Последняя карточка перемещена {n} минуту назад","live.last.min.other":"Последняя карточка перемещена {n} минуты назад","live.last.hour.one":"Последняя карточка перемещена {n} час назад","live.last.hour.other":"Последняя карточка перемещена {n} часа назад","live.last.day.one":"Последняя карточка перемещена {n} день назад","live.last.day.other":"Последняя карточка перемещена {n} дня назад","live.offline":"Живая доска немного отдыхает. Загляните позже.","live.cols":"Бэклог|К выполнению|В работе|Команда проверяет|Тебе на тест|Для команды|Готово","pitch.words.few":"{n} слова","pitch.words.many":"{n} слов","pitch.letters.few":"{n} буквы","pitch.letters.many":"{n} букв","pitch.chars.few":"{n} символа","pitch.chars.many":"{n} символов","count.line.html.few":"{n} карточки на доске прямо сейчас","count.line.html.many":"{n} карточек на доске прямо сейчас","tl.cards.few":"{n} карточки","tl.cards.many":"{n} карточек","live.last.min.few":"Последняя карточка перемещена {n} минуты назад","live.last.min.many":"Последняя карточка перемещена {n} минут назад","live.last.hour.few":"Последняя карточка перемещена {n} часа назад","live.last.hour.many":"Последняя карточка перемещена {n} часов назад","live.last.day.few":"Последняя карточка перемещена {n} дня назад","live.last.day.many":"Последняя карточка перемещена {n} дней назад"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботы.","Делегировано."]},{"n":2,"texts":["Канбан роботов.","Агенты, организованные.","Идеи воплощены."]},{"n":3,"texts":["Канбан для роботов.","Идеи становятся функциями.","Бесплатный канбан агентов."]},{"n":5,"texts":["Канбан-доска, которой управляют агенты.","Ты пишешь карточки. Агенты строят.","Бесплатно, локально, проверено, чуть нелепо."]},{"n":8,"texts":["Бесплатная канбан-доска на твоём компьютере, где работают ИИ-агенты.","Напиши идею. Агенты построят. Ты примешь.","Agile для одного человека и многих терпеливых роботов."]},{"n":13,"texts":["Канбан-доска на твоём компьютере, где карточки берут в работу ИИ-агенты.","Напиши идею. Целая команда агентов её построит. Потом тестировщик всё проверит, и ты принимаешь.","Бесплатно, без аккаунтов и трекеров: доска, пара роботов и ты за главного."]},{"n":21,"texts":["AI-gile это канбан-доска для работы с ИИ-агентами, которые пишут код. Они берут карточки, а ты проверяешь и принимаешь результат.","У каждого проекта есть лид и команда ИИ-агентов. Оставь комментарий к любой карточке, и команда берётся за дело.","Бесплатный личный список дел, который работает на твоём компьютере. Работают роботы. А говорит «да» только один человек: ты."]},{"n":34,"texts":["Ты кладёшь идеи на доску. Команда ИИ-агентов превращает их в работающие функции, проверяет и возвращает тебе с шагами для пробы. Пока ты не скажешь «готово», ничто не считается готовым.","AI-gile это самодельная канбан-доска, которую Рич построил с огромной помощью агентов, которыми она теперь и управляет. Она бесплатна, работает на твоём компьютере и достаётся друзьям, а не продаётся.","Представь обычную канбан-доску с колонками от бэклога до «Готово», только карточки здесь берут ИИ-агенты. Они докладывают о ходе работы, задают вопросы, когда застряли, и всегда ждут твоего одобрения."]},{"n":55,"texts":["AI-gile это канбан-доска, где команда состоит из ИИ-агентов. У каждого проекта есть лид, который планирует работу, и помощники, которые её делают. Когда функция готова, ИИ-тестировщик пробует её и делает скриншот, а потом она попадает в твою стопку. Ты принимаешь её или оставляешь комментарий, и агенты переделывают.","Всё началось с того, что один человек пытался уследить сразу за множеством сеансов ИИ-программирования, и это выросло в настоящую доску. Она работает на твоём компьютере, не требует аккаунта и не ставит трекеры. Бесплатна для друзей и всех любопытных. Она ещё и недоделана, так что жди шероховатостей и сюрпризов.","Вот честная версия. Идеи по-прежнему придумываешь ты, и результат по-прежнему проверяешь ты. А AI-gile делает всё, что между ними: держит карточки в порядке, будит нужного агента, когда ты комментируешь, показывает, что именно изменилось, и собирает всё это в одну короткую стопку для тебя. Никакой магии, просто аккуратная работа, которую больше не нужно делать руками."]},{"n":89,"texts":["AI-gile это бесплатная канбан-доска, которая работает на твоём собственном компьютере. Вместо людей у каждого проекта команда ИИ-агентов: лид, который превращает твои идеи в карточки и план, и помощники, которые берут карточки по порядку важности. Когда что-то построено, ИИ-тестировщик проходит шаги проверки и показывает, что увидел. Потом результат ждёт в одной стопке под названием «Тебе». Ты принимаешь его или оставляешь комментарий, и команда пробует ещё раз. До «Готово» ничто не доходит без тебя.","Есть и неожиданные возможности. Ночной дозор пополняет колонку «К выполнению», пока ты спишь, и выбирает карточки, на которые не нужен твой ответ. Счётчик токенов показывает, сколько агенты израсходовали сегодня и за неделю, а режим без токенов велит им прекратить траты. Можно переписываться с друзьями, а личные сообщения защищены сквозным шифрованием. Доска говорит примерно на 120 языках, включая нидерландский, фламандский, пиратский и клингонский. Ничто из этого не стоит ни копейки, и никто не пытается тебе это продать.","AI-gile это небольшой личный проект, а не компания. Рич хотел присматривать за несколькими проектами с ИИ-программированием, не открывая каждое приложение, и вместе с агентами построил для этого доску, а затем с её помощью достроил всё остальное. Сейчас это закрытая пре-альфа: по большей части работает, но только у горстки друзей. Здесь нет страницы с ценами, рассылки и плана роста. Если звучит полезно, попроси попробовать, когда доступ чуть расширится. Сейчас она держится на терпении агентов и на отзывах друзей. Каждый отзыв превращается в карточку, а карточка рано или поздно превращается в готовую функцию."]},{"n":144,"texts":["AI-gile это канбан-доска для одного человека и множества ИИ-агентов. Она работает на твоём собственном компьютере и совершенно бесплатна. Ты добавляешь проекты, и у каждого проекта появляются лид и небольшая команда. Ты общаешься с лидом, как в Discord, и описываешь идею; лид превращает её в карточки и план, а потом ждёт, пока ты нажмёшь Go. Команда проходит по карточкам в порядке важности, пользуясь простой командной строкой, сделанной для языковых моделей. Прежде чем что-либо вернётся к тебе, ИИ-тестировщик проходит шаги в копии приложения и прикладывает скриншот. Готовая работа попадает в твою стопку вместе с изменёнными файлами и diff. Ты принимаешь её или оставляешь комментарий, и команда просыпается и пробует снова. Переместить карточку в «Готово» можешь только ты.","День с AI-gile выглядит примерно так. Вечером ты оставляешь несколько комментариев: эта кнопка не на месте, тот список надо отсортировать, а нельзя ли тёмную тему. И идёшь спать. Агенты читают комментарии, вносят правки, проверяют их и возвращают тебе. Если «К выполнению» пустеет, ночной дозор наполняет колонку из бэклога карточками, на которые не нужен твой ответ. Утром тебя ждёт одна короткая стопка: пара вопросов и несколько вещей на пробу, к каждой шаги, которые осилит сонный человек, и скриншот, где всё работает. Ты пролистываешь, принимаешь хорошее и возвращаешь остальное. Если что-то не понравилось, пишешь комментарий, и цикл начинается заново, без совещаний и без обид. Лид следит, чтобы работа шла по порядку, а скрам-мастер напоминает застрявшим карточкам, что они застряли. Счётчик токенов показывает расход, а режим без токенов выручает в скромные недели. Потом ты завтракаешь, а с этим агенты пока не помогут.","Сначала о том, чем AI-gile не является. Это не стартап, не товар на продажу, и никто не собирает твои данные. Это бесплатная доска, которая работает на твоём компьютере, без аккаунтов, трекеров и cookie. А вот что это такое: одно аккуратное место, где видны все проекты с ИИ-программированием сразу, где карточки делает команда агентов, а решения принимаешь ты. Она объединяет похожие карточки, исправляет запутанные названия и следит, чтобы код оставался лёгким. Она говорит примерно на 120 языках, от нидерландского и фламандского до пиратского и клингонского. Друзья могут переписываться друг с другом приватно и с шифрованием. Её построили Рич и множество терпеливых агентов, по большей части пользуясь ею же. Это закрытая пре-альфа, так что местами шероховато. Если звучит весело, попроси вежливо, и, возможно, попадёшь раньше других."]}],"quips":{"1":"Одно слово. Смело. Возможно, слишком смело.","3":"Три слова. Уже честнее большинства страниц о продуктах.","8":"Восемь слов. Всё ещё короче стендапа.","21":"Кстати, длины это story points. Конечно же.","55":"Пятьдесят пять слов. Пока ты читал, две карточки успели завершиться.","144":"Это самый длинный вариант. Варианта 233 нет. Агенты ушли спать."}},"timeline":{"first-idea.name":"Первая идея","first-idea.line":"Самый первый разговор, когда кода ещё не было.","first-board.name":"Первая доска","first-board.line":"Доска, которая следит за собственной разработкой: карточки, колонки, перетаскивание, проекты.","team-roles.name":"Команда и роли","team-roles.line":"Профили агентов, шаблоны команд, пространства и кто чем занят.","install.name":"Установка и релизы","install.line":"Архив, который друг сможет установить, самообновление, каналы и откат.","usage-saver.name":"Экономия расхода","usage-saver.line":"Измерять стоимость запусков, держать код лёгким, беречь лимит.","friends.name":"Друзья и общий доступ","friends.line":"Личные сообщения, зашифрованный ретранслятор, приглашения, роли и общие проекты.","languages.name":"Языки","languages.line":"Каждый текст на экране в языковом файле, сначала нидерландский и фламандский.","ai-tester.name":"ИИ-тестировщик","ai-tester.line":"Тестировщик первым проверяет каждую сдачу и показывает, что увидел.","website.name":"Сайт","website.line":"aigile.lol, тизер и эта хронология.","streaming.name":"Чат и стриминг","streaming.line":"Discord, Twitch, OBS, режим стримера, гифки и эмодзи.","no-ai.name":"Версия без ИИ","no-ai.line":"Доска для тех, кто пишет код без ИИ, и публичные доски.","night-watch.name":"Ночной дозор","night-watch.line":"Сторож и скрам-мастер держат команды в работе, пока ты спишь.","p-more.name":"Всё остальное","p-more.line":"Идеи поменьше, которые ждут своей очереди.","p-android.name":"Телефон и Android","p-android.line":"Доступ к доске с телефона, а потом и родное приложение для Android.","p-release.name":"Альфа и дальше","p-release.line":"Закрытая альфа, живой сайт, затем бета.","p-languages.name":"Ещё языки","p-languages.line":"130 языков и режим погружения для тех, кто учит язык.","p-engines.name":"Ещё ИИ-движки","p-engines.line":"Выбирай Claude, Codex, Gemini, Copilot или Cursor для каждого агента.","p-pro.name":"Профессиональная практика","p-pro.line":"Метки риска, барьеры слияния, карточки инцидентов и ограждения.","p-self.name":"Забота о тебе","p-self.line":"Режим усталости, напоминания о заботе о себе и 4:20.","p-servers.name":"Серверы и масштаб","p-servers.line":"Общие настройки сервера, роли и планы на рост.","p-livestream.name":"Дополнения для стриминга","p-livestream.line":"Чат Twitch, свои эмодзи и публичный просмотр вживую."},"words":{"button":"📖 Профессиональный жаргон","h":"📖 Словарик","intro":"Слова, которые встречаются в AI-gile, простым языком: как это строить, как безопасно менять, как сделать, чтобы всё работало для тех, кто этим пользуется, и как работать командой вместе с ИИ.","search":"Найти слово…","none":"Такого слова нет.","close":"Закрыть","count":{"one":"{count} слово","other":"Слов: {count}"},"groups":[{"id":"build","name":"🛠️ Как это строят"},{"id":"change","name":"🔀 Безопасные изменения"},{"id":"run","name":"🛎️ Как вести сервис"},{"id":"team","name":"🤝 Работа в команде (и с ИИ)"}],"list":[{"id":"repo","g":"build","word":"Репозиторий","text":"Папка проекта с кодом и полной историей коммитов, обычно хранится ещё и на GitHub.","also":["репо","репозитория","репозитории"]},{"id":"branch","g":"build","word":"Ветка","text":"Отдельная линия работы в коде, чтобы вносить изменения, не трогая основную версию.","also":["ветки","ветку","ветке","веток","веткой"]},{"id":"commit","g":"build","word":"Коммит","text":"Сохранённый снимок кода с короткой заметкой о том, что изменилось. К любому из них всегда можно вернуться.","also":["коммиты","коммита","коммитов","коммиту","коммите"]},{"id":"push","g":"build","word":"Пуш","text":"Отправка сохранённых снимков (коммитов) с этого компьютера на GitHub, чтобы они были в резерве и доступны другим."},{"id":"merge","g":"build","word":"Мерж","text":"Слияние изменений ветки обратно в основную версию."},{"id":"pr","g":"build","word":"Пулл-реквест","text":"Просьба проверить изменения ветки и влить их в основную версию.","also":["PR"]},{"id":"refactor","g":"build","word":"Рефакторинг","text":"Наведение порядка в коде без изменения того, что он делает: файлы меньше, названия понятнее, повторов меньше."},{"id":"bug","g":"build","word":"Баг","text":"Что-то, что работает не так, как должно.","also":["баги","бага","багов","багу","багом","ошибка"]},{"id":"test","g":"build","word":"Тест","text":"Проверка готовой работы: делает ли она то, о чём просили, прежде чем ты её примешь.","also":["тесты","теста","тесту","тестов","тестом","тестировать","тестирование","протестируешь","тесте"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Сокращение от quality assurance, то есть контроль качества: автоматические проверки, которые запускаются до того, как что-то выйдет в прод. Если QA красный, что-то не прошло, и выпускать нельзя, пока это не исправят.","also":["контроль качества","проверки качества"]},{"id":"deploy","g":"change","word":"Деплой","text":"Выкладка новой версии в работу, например на сервер, где ею пользуются люди."},{"id":"release","g":"change","word":"Релиз","text":"Набор готовой работы с названием, который выходит в прод целиком, с короткими заметками о том, что изменилось. 🚀 Релизы пишет заметки по сделанным карточкам.","also":["релизы","выпуск","release"]},{"id":"rollback","g":"change","word":"Откат","text":"Возврат к последней рабочей версии, когда новая создаёт проблемы. В AI-gile из этого получается чек-лист шагов отмены, которые записаны в каждом изменении.","also":["откатить","роллбэк","rollback"]},{"id":"live","g":"change","word":"Прод","text":"Настоящая версия, которой пользуются люди, в отличие от копии, на которой что-то пробуют. Разработчики говорят «прод» или «продакшн».","also":["продакшн","продакшен","боевая версия","live"],"noTip":1},{"id":"change","g":"change","word":"Изменение","text":"Запланированное изменение в том, на что полагаются люди, сначала описанное: что, зачем, какой риск, когда и как его отменить. Начни с 🔀 Создать изменение.","also":["изменения","запрос на изменение","change request"],"noTip":1},{"id":"risk","g":"change","word":"Риск","text":"То, что может пойти не так, с оценкой: насколько это вероятно и насколько плохо будет. ⚠️ Риски держит их в одном списке, от самой высокой оценки, у каждого есть дата, когда посмотреть снова.","also":["риски","реестр рисков"]},{"id":"chgwin","g":"change","word":"Окно изменений","text":"Время, когда изменения можно выпускать в прод, например спокойный вечер вторника. Вне окна карточку изменения нельзя завершить, если только это не срочный случай.","also":["окна изменений","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Быстрое голосование прямо перед выпуском изменения: каждый, кто должен его одобрить, говорит Go или No go. Изменение идёт дальше, только когда все согласны.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Подтверждение","text":"Ожидание «да» перед началом работы. Карточка от друга или изменение ждёт в ✅ Подтверждениях, пока ты не одобришь или не отклонишь его.","also":["подтверждения","одобрение","согласование"]},{"id":"quiettime","g":"change","word":"Тихое время","text":"Отрезок времени, например стрим, демо или ночь, когда ничего не выходит в прод. Команды продолжают работать и тестировать, но выпуск ждёт, пока он не закончится. В других местах это называют заморозкой изменений.","also":["тихие часы","заморозка изменений","change freeze"]},{"id":"service","g":"run","word":"Сервис","text":"То, что ты сделал и на что полагаются люди, например сайт или приложение, и за чем присматривают, чтобы оно продолжало работать. Отметь «Этот проект — сервис» и напиши, что он даёт, кто им пользуется и кто дежурит.","also":["сервисы","услуга"]},{"id":"uptime","g":"run","word":"Проверка доступности","text":"Автоматическая проверка каждые несколько минут, что твой сервис всё ещё отвечает. Если она несколько раз подряд не проходит, AI-gile сам открывает карточку инцидента.","also":["аптайм","uptime","доступность"]},{"id":"statuspage","g":"run","word":"Страница статуса","text":"Публичная страница, которая показывает, работает ли сервис (зелёный, оранжевый или красный), и последнее обновление, чтобы пользователи могли проверить сами, а не спрашивать.","also":["страницы статуса","статус-страница","status page"]},{"id":"desk","g":"run","word":"Служба поддержки","text":"Место, куда приходят вопросы и сообщения от людей, которые пользуются твоим сервисом. AI-gile относит каждое к запросу, инциденту или идее и подсказывает, если оно похоже на то, о чём уже сообщали.","also":["службы поддержки","поддержка","service desk","help desk","helpdesk","хелпдеск"]},{"id":"svcrequest","g":"run","word":"Запрос на обслуживание","text":"Кто-то просит о чём-то обычном, например новую учётную запись или немного помощи, а не сообщает, что что-то сломалось. Он ждёт своей очереди; инцидент идёт первым.","also":["запросы на обслуживание","запрос"]},{"id":"incident","g":"run","word":"Инцидент","text":"Что-то, что сломалось для пользователей прямо сейчас, например сайт лежит. Карточка 🔥 инцидента идёт без очереди: сначала надо, чтобы всё снова заработало.","also":["инциденты","сбой","авария"]},{"id":"major","g":"run","word":"Крупный инцидент","text":"Большой инцидент: затронуто много людей или под угрозой деньги или данные. Одна кнопка бросает на него все команды (рой), будит дежурного и просит обновление статуса каждые 30 минут.","also":["крупные инциденты","major incident"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Быть тем, кто отвечает, когда что-то ломается, даже ночью. У каждого сервиса есть дежурный из команды, которого будят первым при его инцидентах.","also":["дежурный","на связи","on call","on-call"]},{"id":"replyby","g":"run","word":"Срок ответа","text":"Сколько карточка может ждать первого ответа, например час для инцидента. Потом у неё появляются красные часы, чтобы ничего тихо не забылось. Ещё это называют целевым временем реакции.","also":["сроки ответа","время реакции","целевое время реакции"]},{"id":"postmortem","g":"run","word":"Разбор инцидента","text":"Короткий взгляд назад после инцидента: что случилось, что помогло и что изменить, без поиска виноватых. Без него инцидент нельзя закрыть.","also":["пост-мортем","постмортем","post-mortem","разборы инцидентов"]},{"id":"problem","g":"run","word":"Проблема","text":"Скрытая причина одного или нескольких инцидентов. Карточка 🧩 проблемы собирает вместе инциденты, которые повторяются, чтобы найти причину и исправить её насовсем.","also":["проблемы"],"noTip":1},{"id":"rootcause","g":"run","word":"Первопричина","text":"Настоящая причина поломки, а не только то, что было видно со стороны. Исправь первопричину, и инцидент перестанет повторяться.","also":["первопричины","корневая причина","root cause"]},{"id":"workaround","g":"run","word":"Обходной путь","text":"Способ сохранить работу, пока не готово настоящее исправление, например перезапускать то, что зависает. Он записан в карточке проблемы, чтобы никому не пришлось придумывать его заново.","also":["обходные пути","временное решение","воркэраунд","workaround"]},{"id":"knownerror","g":"run","word":"Известная ошибка","text":"Проблема, причина которой понятна и для которой есть обходной путь, но которая ещё не исправлена. 🧩 Известные ошибки показывает их список, чтобы все пользовались обходным путём, а не копали заново.","also":["известные ошибки","known error"]},{"id":"runbook","g":"run","word":"Ранбук","text":"Пошаговая инструкция, как исправить известный вид неполадки, чтобы каждый раз делать это одинаково и быстро. После крупного инцидента команда может предложить ранбук, а ты его одобришь.","also":["ранбуки","runbook","инструкция","регламент"]},{"id":"ci","g":"run","word":"Элемент конфигурации","text":"Одна вещь, от которой зависит твой сервис: например сервер, домен, сертификат, ключ или поставщик. 🗂️ Элементы конфигурации перечисляет их для каждого сервиса, чтобы было видно, что задевает инцидент и что нужно продлить или забэкапить.","also":["элементы конфигурации","элементов конфигурации"]},{"id":"expiry","g":"run","word":"Срок действия","text":"AI-gile следит за датами, например когда истекает сертификат или домен. За 30 дней до даты он создаёт одну карточку на продление, чтобы ничего внезапно не перестало работать.","also":["сроки действия","истечение срока","контроль сроков"]},{"id":"backup","g":"run","word":"Резервная копия","text":"Сохранённая раньше копия твоих данных, чтобы было к чему вернуться, если что-то потеряется или испортится. AI-gile каждый день делает резервную копию твоих досок.","also":["бэкап","бэкапы","резервные копии","backup"]},{"id":"restore","g":"run","word":"Восстановление","text":"Возврат данных из резервной копии. Копия по-настоящему чего-то стоит, только когда ты знаешь, что из неё можно восстановиться, поэтому иногда стоит это проверять.","also":["восстановить","восстановлено","restore"]},{"id":"svcreview","g":"run","word":"Обзор сервиса","text":"Взгляд назад на один месяц работы сервиса: открытые и исправленные инциденты, как быстро люди получали ответ, доступность и потраченные токены. Ежемесячный обзор показывает это для каждого сервиса.","also":["обзоры сервиса","ежемесячный обзор","ежемесячные обзоры"]},{"id":"accessreview","g":"run","word":"Проверка доступа","text":"Раз в 90 дней проверяем, у кого ещё есть доступ: ссылки для общего доступа, роли друзей и хранимые секреты. Каждый пункт ты оставляешь или удаляешь, чтобы старый доступ не висел забытым.","also":["проверки доступа"]},{"id":"improvements","g":"run","word":"Список улучшений","text":"Всё, что команда решила делать лучше, в одном месте: предложения с ретро, действия из разборов и исправления проблем, у каждого свой статус. Ищи в 📈 Улучшения.","also":["списки улучшений","улучшения"]},{"id":"tokencap","g":"run","word":"Лимит токенов","text":"Месячный лимит токенов, которые могут потратить агенты сервиса. На 80% ты получаешь предупреждение; на 100% их фоновая работа ждёт следующего месяца или пока ты не поднимешь лимит.","also":["лимиты токенов","месячный лимит токенов"]},{"id":"backlog","g":"team","word":"Бэклог","text":"Идеи и работа, которые ещё не запланированы. Пока они не перейдут в «К выполнению», над ними никто не работает."},{"id":"sprint","g":"team","word":"Спринт","text":"Короткий отрезок работы (часто неделя или две) с согласованным набором карточек, которые нужно закончить.","also":["спринта","спринту","спринте","спринты","спринтов","спринтом"]},{"id":"standup","g":"team","word":"Стендап","text":"Короткая сверка в команде: что сделано, что дальше и что мешает.","also":["стендапа","стендапы","стендапов","стендапе","стенд-ап","стендапам"]},{"id":"kanban","g":"team","word":"Канбан","text":"Доска с колонками (К выполнению, В работе, Готово), где карточки движутся слева направо по ходу работы."},{"id":"wip","g":"team","word":"WIP-лимит","text":"Work in progress: максимум карточек в колонке, чтобы команда заканчивала дела, прежде чем начинать новые.","also":["WIP"]},{"id":"dod","g":"team","word":"Критерии «Сделано»","text":"Короткий чек-лист команды о том, что значит «готово», например проверено и объяснено, прежде чем карточка попадёт к тебе. Его близнец, критерии «Готово к работе», говорит, когда карточка достаточно понятна, чтобы начать.","also":["Definition of Done","DoD","критерии готовности","критерии «Готово к работе»","Definition of Ready"]},{"id":"testpile","g":"team","word":"Стопка тестов","text":"Готовые карточки, которые ждут, когда ты их попробуешь, одна за другой. Прими карточку или верни её с заметкой, и появится следующая.","also":["стопки тестов","test pile"]},{"id":"retro","g":"team","word":"Ретро","text":"Взгляд назад на то, как работает команда, чтобы договориться об одной вещи, которую сделать лучше. В AI-gile ретро предлагает изменение в правилах работы команды, а ты отвечаешь «Давай» или «Пока нет».","also":["ретроспектива","ретроспективы"]},{"id":"peerreview","g":"team","word":"Взаимная проверка","text":"Вторая пара глаз: другой ИИ проверяет работу по каждой карточке, прежде чем она дойдёт до тебя, так что ошибок проходит меньше.","also":["ревью","код-ревью","code review","peer review"]},{"id":"swarm","g":"team","word":"Рой","text":"Все на палубу: каждая команда бросает другую работу и помогает с одним срочным проектом, пока всё не решится. Остальные проекты в это время ждут.","also":["режим роя","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Тот, кто следит, чтобы работа шла: замечает застрявшие карточки, подталкивает команды и напоминает тебе, что ждёт. В AI-gile этим занимается Lead Scrum Master во всех проектах.","also":["скрам-мастер","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Агент","text":"ИИ, который самостоятельно работает над задачей: читает код, вносит изменения, запускает проверки и докладывает.","also":["агенты","агента","агентов","агенту","агентом"]},{"id":"token","g":"team","word":"Токен","text":"Единица, в которой считается использование ИИ: примерно несколько букв прочитанного или написанного текста. Меньше токенов — больше остаётся от тарифа.","also":["токены","токена","токенов","токенов","токену"]},{"id":"hook","g":"team","word":"Хук","text":"Небольшая команда, которая запускается сама в заданный момент, например при старте ИИ-сессии, чтобы команда слышала твои комментарии.","also":["хуки","хука","хуков"]}]}};
